async function getMyDeviceId() { let did = await AsyncStorage.getItem('deviceId'); if (!did) { did = `${Platform.OS}_${Device.modelName || 'phone'}_${Math.random().toString(36).slice(2, 9)}`; await AsyncStorage.setItem('deviceId', did); } return did; }
let lastPosCache = null;
async function velocityCheck(newPos) { if (!lastPosCache) { lastPosCache = { lat: newPos.coords.latitude, lng: newPos.coords.longitude, time: Date.now() }; return false; } const dist = getDistanceMeters(lastPosCache.lat, lastPosCache.lng, newPos.coords.latitude, newPos.coords.longitude); const timeSec = (Date.now() - lastPosCache.time) / 1000; const speedMs = dist / Math.max(1, timeSec); lastPosCache = { lat: newPos.coords.latitude, lng: newPos.coords.longitude, time: Date.now() }; return speedMs > 20 && dist > 500; }

const LIBRARY_COORDINATES = { "prempeh": { latitude: 6.67493, longitude: -1.57123 }, "engineering": { latitude: 6.67455, longitude: -1.56985 }, "science": { latitude: 6.67715, longitude: -1.57015 }, "architecture": { latitude: 6.67685, longitude: -1.57255 }, "art": { latitude: 6.67620, longitude: -1.57310 }, "law": { latitude: 6.67405, longitude: -1.57305 }, "business": { latitude: 6.67380, longitude: -1.57220 }, "pharmacy": { latitude: 6.67490, longitude: -1.56850 }, "agriculture": { latitude: 6.67580, longitude: -1.56890 }, "health": { latitude: 6.67510, longitude: -1.56780 }, "humanities": { latitude: 6.67320, longitude: -1.57280 }, "idl": { latitude: 6.67290, longitude: -1.57150 }, "forestry": { latitude: 6.67590, longitude: -1.56810 }, "grinds": { latitude: 6.67420, longitude: -1.57180 } };
function getLibCoords(lib) { if (lib?.latitude && lib?.longitude) return { latitude: lib.latitude, longitude: lib.longitude }; return LIBRARY_COORDINATES[lib?.id] || { latitude: 6.67493, longitude: -1.57123 }; }
const KNUST_WALK_GRAPH = { "prempeh": { neighbors: { "grinds": 85, "engineering": 220, "science": 310, "business": 180, "humanities": 350 } }, "engineering": { neighbors: { "prempeh": 220, "pharmacy": 90, "agriculture": 150, "forestry": 180, "health": 280 } }, "science": { neighbors: { "prempeh": 310, "architecture": 120, "pharmacy": 280 } }, "architecture": { neighbors: { "science": 120, "art": 80, "prempeh": 250 } }, "art": { neighbors: { "architecture": 80, "law": 180, "business": 150 } }, "law": { neighbors: { "art": 180, "business": 110, "humanities": 180 } }, "business": { neighbors: { "law": 110, "art": 150, "prempeh": 180, "humanities": 150, "idl": 140 } }, "pharmacy": { neighbors: { "engineering": 90, "health": 120, "agriculture": 80 } }, "agriculture": { neighbors: { "pharmacy": 80, "forestry": 60, "engineering": 150 } }, "health": { neighbors: { "pharmacy": 120, "engineering": 280 } }, "humanities": { neighbors: { "business": 150, "law": 180, "idl": 100, "prempeh": 350 } }, "idl": { neighbors: { "humanities": 100, "business": 140 } }, "forestry": { neighbors: { "agriculture": 60, "engineering": 180 } }, "grinds": { neighbors: { "prempeh": 85 } } };
function getWalkingDistanceMeters(fromId, toId) { if (fromId === toId) return 30; const graph = KNUST_WALK_GRAPH; if (!graph[fromId] || !graph[toId]) return 500; const dist = {}; Object.keys(graph).forEach(k => dist[k] = Infinity); dist[fromId] = 0; const visited = {}; for (let i = 0; i < Object.keys(graph).length; i++) { let min = Infinity, node = null; Object.keys(dist).forEach(n => { if (!visited[n] && dist[n] < min) { min = dist[n]; node = n; } }); if (!node) break; visited[node] = true; Object.entries(graph[node].neighbors || {}).forEach(([nbr, w]) => { if (dist[node] + w < dist[nbr]) dist[nbr] = dist[node] + w; }); } return dist[toId] || 500; }
function getWalkingTimeMins(m) { return Math.max(1, Math.ceil(m / 80)); }
function getDistanceMeters(lat1, lon1, lat2, lon2) { const R = 6371000; const dLat = (lat2 - lat1) * Math.PI / 180; const dLon = (lon2 - lon1) * Math.PI / 180; const a = Math.sin(dLat / 2) ** 2 + Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * Math.sin(dLon / 2) ** 2; return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a)); }
function validateSeats(input, lib) { if (input === '' || input == null) return { ok: false, msg: "Enter seats" }; const n = Number(String(input).trim()); if (isNaN(n)) return { ok: false, msg: `Enter 0 to ${lib.totalSeats}` }; if (!Number.isInteger(n)) return { ok: false, msg: "Whole number only" }; if (n < 0) return { ok: false, msg: "Can't be negative" }; if (n > lib.totalSeats) return { ok: false, msg: `Max ${lib.totalSeats}` }; return { ok: true, value: n }; }
function toSeconds(ts) { try { if (!ts) return 0; if (typeof ts.seconds === 'number') return ts.seconds; if (typeof ts.toMillis === 'function') return Math.floor(ts.toMillis() / 1000); if (ts instanceof Timestamp) return ts.seconds; if (ts._seconds) return ts._seconds; if (ts instanceof Date) return Math.floor(ts.getTime() / 1000); if (typeof ts === 'number') return Math.floor(ts / 1000); return 0; } catch { return 0; } }
function formatTimeAgo(ts) { const sec = toSeconds(ts); if (!sec) return "Just now"; const diff = Date.now() / 1000 - sec; if (diff < 60) return "Just now"; if (diff < 3600) return `${Math.floor(diff / 60)}m ago`; if (diff < 86400) { const h = Math.floor(diff / 3600); return h === 1 ? "1h ago" : `${h}h ago`; } const d = Math.floor(diff / 86400); return d === 1 ? "1d ago" : `${d}d ago`; }
function getRealTimeSeats(lib) { const sec = toSeconds(lib.lastVerified); if (!sec) return { state: "FRESH" }; const m = (Date.now() / 1000 - sec) / 60; if (m > 120) return { state: "GHOST" }; if (m > 60) return { state: "EXPIRED" }; if (m > 15) return { state: "STALE" }; return { state: "FRESH" }; }
function getStatusFromSeats(seats, total) { if (seats <= 0) return 'full'; if (seats < total * 0.3) return 'half'; return 'empty'; }
async function checkAndroidMockNative(pos) { try { return pos?.mocked === true || pos?.coords?.mocked === true; } catch { return false; } }
async function registerPushToken(uid) { try { if (Platform.OS === 'web' || !Device.isDevice) return null; const { status: ex } = await Notifications.getPermissionsAsync(); let final = ex; if (ex !== 'granted') { const { status } = await Notifications.requestPermissionsAsync(); final = status; } if (final !== 'granted') return null; const token = (await Notifications.getExpoPushTokenAsync({ projectId: Constants.expoConfig?.extra?.eas?.projectId })).data; if (token && uid) await setDoc(doc(db, "users", uid), { expoPushToken: token, pushUpdatedAt: serverTimestamp() }, { merge: true }); return token; } catch { return null; } }

// ---- ADMIN ----
function AdminPanel({ onClose, user }) {
  const [isResetting, setIsResetting] = useState(false);
  const [seedLib, setSeedLib] = useState("prempeh"); const [seedSeats, setSeedSeats] = useState(""); const [seedTotal, setSeedTotal] = useState("450"); const [seedName, setSeedName] = useState("Prempeh II Library"); const [seedLat, setSeedLat] = useState(""); const [seedLng, setSeedLng] = useState("");
  const wipeCollection = async (name) => { const snap = await getDocs(collection(db, name)); await Promise.all(snap.docs.map(d => deleteDoc(doc(db, name, d.id)))); };
  const doResetAll = async () => { if (isResetting) return; setIsResetting(true); try { for (const c of ["reports", "queue", "watchlist", "leavingAssignments", "leavingReports", "payments", "activeSeats"]) await wipeCollection(c); Alert.alert("Cleared!"); } catch (e) { Alert.alert(e.message); } setIsResetting(false); };
  const doSeed = async () => { const n = Number(seedSeats); if (isNaN(n)) return Alert.alert("Enter number"); const total = Number(seedTotal) || 200; const lat = Number(seedLat) || LIBRARY_COORDINATES[seedLib]?.latitude || 6.67493; const lng = Number(seedLng) || LIBRARY_COORDINATES[seedLib]?.longitude || -1.57123; const libName = seedName || seedLib; const status = getStatusFromSeats(n, total); await setDoc(doc(db, "libraries", seedLib), { name: libName, totalSeats: total, availableSeats: n, confirmedStatus: status, lastVerified: serverTimestamp(), updatedAt: serverTimestamp(), isRealData: true, latitude: lat, longitude: lng, block: "Block A Row 1-5" }, { merge: true }); Alert.alert("Seeded REAL", `${libName} = ${n} seats`); };
  const inp = { backgroundColor: '#f1f5f9', padding: 14, borderRadius: 12, marginTop: 10 };
  return (<ScrollView style={{ flex: 1, paddingTop: 60, padding: 20, backgroundColor: '#f8fafc' }}><Text style={{ fontWeight: '900', fontSize: 20 }}>Admin Panel</Text><Text style={{ color: '#64748b', marginTop: 4 }}>{user.uid}</Text><View style={{ backgroundColor: 'white', padding: 16, borderRadius: 20, marginTop: 16 }}><Text style={{ fontWeight: '900' }}>Seed REAL Count</Text><TextInput placeholder="prempeh" value={seedLib} onChangeText={setSeedLib} style={inp} /><TextInput placeholder="Library Name" value={seedName} onChangeText={setSeedName} style={inp} /><TextInput placeholder="Total Seats" value={seedTotal} onChangeText={setSeedTotal} keyboardType="numeric" style={inp} /><TextInput placeholder="Free seats" value={seedSeats} onChangeText={setSeedSeats} keyboardType="numeric" style={inp} /><TextInput placeholder="Latitude" value={seedLat} onChangeText={setSeedLat} keyboardType="decimal-pad" style={[inp, { backgroundColor: '#dcfce7' }]} /><TextInput placeholder="Longitude" value={seedLng} onChangeText={setSeedLng} keyboardType="decimal-pad" style={[inp, { backgroundColor: '#dcfce7' }]} /><TouchableOpacity onPress={doSeed} style={{ backgroundColor: '#22c55e', padding: 15, borderRadius: 12, marginTop: 12 }}><Text style={{ color: 'white', textAlign: 'center', fontWeight: '900' }}>Seed REAL Count</Text></TouchableOpacity><TouchableOpacity onPress={doResetAll} style={{ backgroundColor: '#ef4444', padding: 15, borderRadius: 12, marginTop: 10 }}><Text style={{ color: 'white', textAlign: 'center', fontWeight: '900' }}>CLEAR ALL DATA</Text></TouchableOpacity></View><TouchableOpacity onPress={onClose} style={{ backgroundColor: '#0f172a', padding: 14, borderRadius: 12, marginTop: 20, marginBottom: 40 }}><Text style={{ color: 'white', textAlign: 'center' }}>Back</Text></TouchableOpacity></ScrollView>);
}

